"""Complete practice flow with clearly original disposable fixtures only."""
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
import shutil
import re
import os
from urllib.parse import unquote

BASE='http://127.0.0.1:8092'
ROOT=Path(__file__).resolve().parents[1]
ENGINE=os.getenv('CAFCC_BROWSER_ENGINE','chromium');TARGET='TEST-WEBKIT-V051-BROWSER' if ENGINE=='webkit' else 'TEST-V051-BROWSER'


def login(page,user):
    page.goto(BASE+'/wp-login.php',wait_until='networkidle');page.locator('#user_login').fill(user);page.locator('#user_pass').fill('cafcc-disposable-only');page.locator('#wp-submit').click();page.wait_for_load_state('networkidle')


def reader(page):
    page.goto(BASE+'/?cafcc_view=explorer',wait_until='networkidle');page.locator('[data-filter=search]').fill(TARGET);page.locator('[data-filter=search]').press('Enter');card=page.locator('.cc-question');page.wait_for_function("document.querySelector('[data-cafcc-explorer]')&&!document.querySelector('[data-cafcc-explorer]').hasAttribute('aria-busy')");expect(card).to_have_count(1);expect(card.get_by_role('button',name='Start',exact=True)).to_be_enabled();return card


with sync_playwright() as p:
    launch={'headless':True}
    if ENGINE=='chromium':launch.update(args=['--no-sandbox','--disable-dev-shm-usage'],**({'executable_path':shutil.which('chromium')} if shutil.which('chromium') else {}))
    browser=getattr(p,ENGINE).launch(**launch)
    admin=browser.new_page(viewport={'width':1024,'height':1366});login(admin,'test_admin');admin.goto(BASE+'/wp-admin/admin.php?page=cafcc-studio',wait_until='networkidle');admin.locator('#studio-search').fill(TARGET);expect(admin.locator('#studio-rows tr')).to_have_count(1);admin.locator('#studio-rows tr button').first.click();expect(admin.locator('.cc-review-checklist')).to_be_visible();admin.on('dialog',lambda dialog:dialog.accept());before_revision=int(re.search(r'Revision (\d+)',admin.locator('#studio-detail small').inner_text())[1]);admin.get_by_role('button',name='Confirm my manual PDF comparison',exact=True).click();expect(admin.locator('#studio-detail small')).to_contain_text('Revision '+str(before_revision+1));admin.locator('[data-owner-action=publish]').click();expect(admin.locator('#studio-detail small')).to_contain_text('approved');admin.screenshot(path=str(ROOT/f'docs/previews/v051-{ENGINE}-original-owner-review-ipad.png'),full_page=True,animations='disabled')
    context=browser.new_context(viewport={'width':1024,'height':1366});page=context.new_page();errors=[];answers=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:answers.append(r.url) if '/answers/' in unquote(r.url) else None);login(page,'student_a');card=reader(page);assert 'TEST ORIGINAL shared facts' in card.inner_text();assert not answers;assert '₹40 per period' not in card.inner_text()
    card.get_by_role('button',name='Start',exact=True).click();expect(card.get_by_role('button',name='Pause',exact=True)).to_be_enabled();page.wait_for_timeout(1100);page.reload(wait_until='networkidle');card=page.locator('.cc-question');expect(card.get_by_role('button',name='Pause',exact=True)).to_be_enabled();card.get_by_role('button',name='Pause',exact=True).click();expect(card.get_by_role('button',name='Resume',exact=True)).to_be_enabled();card.get_by_role('button',name='Resume',exact=True).click();expect(card.get_by_role('button',name='Pause',exact=True)).to_be_enabled();card.get_by_label('Practice status',exact=True).select_option('needs_revision');expect(card.locator('.cc-study-feedback')).to_contain_text('saved');card.get_by_role('button',name='Finish',exact=True).click();expect(card.locator('.cc-study-feedback')).to_contain_text('session saved');card.get_by_role('button',name='☆ Important',exact=True).click();expect(card.get_by_role('button',name='★ Important',exact=True)).to_be_visible()
    card.locator('.cc-private-tags summary').click();card.get_by_label('Your private tags (comma separated)',exact=True).fill('Important, Difficult, Revise Again, TEST custom');card.get_by_role('button',name='Save my tags',exact=True).click();expect(card.locator('.cc-study-feedback')).to_contain_text('saved');card.get_by_role('button',name='☆ Bookmark',exact=True).click();expect(card.get_by_role('button',name='★ Bookmarked',exact=True)).to_be_visible();card.locator('.cc-private-notes summary').click();card.get_by_label('Your private note',exact=True).fill('TEST student A persistent v051 note');card.get_by_role('button',name='Save my note',exact=True).click()
    page.evaluate("""()=>{const body=document.querySelector('.cc-question-content .cc-rich-content');const walk=document.createTreeWalker(body,NodeFilter.SHOW_TEXT);while(walk.nextNode()){const n=walk.currentNode,i=n.textContent.indexOf('A learning entity pays ₹120');if(i>=0){const r=document.createRange();r.setStart(n,i);r.setEnd(n,i+26);getSelection().removeAllRanges();getSelection().addRange(r);break;}}}""")
    card.get_by_role('button',name='Highlight selected text',exact=True).click();expect(card.locator('mark[data-study-highlight]')).to_have_count(1)
    card.get_by_role('button',name='Both',exact=True).click();expect(card.locator('.cc-answer-panel')).to_contain_text('₹40 per period');assert len(answers)==1;card.get_by_role('button',name='Answer',exact=True).click();expect(card.locator('.cc-question-content')).to_be_hidden();card.get_by_role('button',name='Question',exact=True).click();expect(card.locator('.cc-question-content')).to_be_visible();expect(card.locator('.cc-answer-panel')).to_be_empty();page.wait_for_function("Number(getComputedStyle(document.querySelector('.cc-question-content .cc-rich-content')).opacity)>.99");assert card.locator('.cc-question-content .cc-rich-content p').first.evaluate('(n)=>getComputedStyle(n).color===getComputedStyle(n.closest(\".cc-portal\")).color');page.screenshot(path=str(ROOT/f'docs/previews/v051-{ENGINE}-original-reader-ipad.png'),full_page=True,animations='disabled')
    page.get_by_role('button',name='Switch to dark mode',exact=True).click();expect(page.locator('.cc-portal')).to_have_attribute('data-cc-theme','dark');assert card.locator('.cc-question-content .cc-rich-content p').first.evaluate('(n)=>getComputedStyle(n).color===getComputedStyle(n.closest(\".cc-portal\")).color');page.screenshot(path=str(ROOT/f'docs/previews/v051-{ENGINE}-original-reader-dark.png'),full_page=True,animations='disabled');page.get_by_role('button',name='Switch to light mode',exact=True).click()
    context.clear_cookies();login(page,'student_a');card=reader(page);card.locator('.cc-private-notes summary').click();expect(card.get_by_label('Your private note',exact=True)).to_have_value('TEST student A persistent v051 note');expect(card.get_by_role('button',name='★ Bookmarked',exact=True)).to_be_visible();expect(card.locator('mark[data-study-highlight]')).to_have_count(1);expect(card.get_by_label('Practice status',exact=True)).to_have_value('needs_revision')
    page.goto(BASE+'/?cafcc_view=dashboard',wait_until='networkidle');expect(page.locator('[data-study-dashboard]')).to_contain_text('Recent timed practice');expect(page.locator('[data-study-dashboard]')).to_contain_text('TEST custom');page.screenshot(path=str(ROOT/f'docs/previews/v051-{ENGINE}-original-dashboard-ipad.png'),full_page=True,animations='disabled')
    other=browser.new_page(viewport={'width':390,'height':844});login(other,'student_b');othercard=reader(other);expect(othercard.get_by_role('button',name='☆ Bookmark',exact=True)).to_be_visible();expect(othercard.get_by_role('button',name='☆ Important',exact=True)).to_be_visible();assert not othercard.locator('mark[data-study-highlight]').count();othercard.locator('.cc-private-notes summary').click();expect(othercard.get_by_label('Your private note',exact=True)).to_have_value('');assert other.evaluate('document.documentElement.scrollWidth<=innerWidth');assert othercard.locator('.cc-rich-content').first.evaluate('(n)=>n.scrollWidth>n.clientWidth');other.screenshot(path=str(ROOT/f'docs/previews/v051-{ENGINE}-original-reader-phone.png'),full_page=True,animations='disabled')
    assert not errors,errors
    browser.close()
print(ENGINE+' V0.5.1 browser passed: original shared scenario, manual source-comparison gate, deliberate Question/Answer/Both, refresh-safe stopwatch lifecycle, notes/bookmarks/tags/highlights across login, real dashboard activity and two-student privacy. Not owner academic approval or physical iPad acceptance.')
